#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int r,c;scanf("%d %d",&r,&c);
vector<vector<int>>g(r,vector<int>(c));
vector<vector<int>>dist(r,vector<int>(c,-1));
queue<pair<int,int>>q;
for(int i=0;i<r;++i)for(int j=0;j<c;++j){
scanf("%d",&g[i][j]);
if(g[i][j]==0){dist[i][j]=0;q.push({i,j});}}
int dx[4]={1,-1,0,0},dy[4]={0,0,1,-1};
while(!q.empty()){auto pr=q.front();q.pop();
for(int d=0;d<4;++d){int nx=pr.first+dx[d],ny=pr.second+dy[d];
if(nx<0||nx>=r||ny<0||ny>=c)continue;
if(dist[nx][ny]==-1){dist[nx][ny]=dist[pr.first][pr.second]+1;q.push({nx,ny});}}}
for(int i=0;i<r;++i){for(int j=0;j<c;++j){if(j)printf(" ");printf("%d",dist[i][j]);}printf("\n");}
return 0;}

